:root {
  --bg: #1b1f3b;
  --panel: #2a2f55;
  --ink: #f4f4ff;
  --accent: #ffd23f;
  --accent2: #4ad6c4;
  --border: #0d0f22;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background:
    repeating-linear-gradient(0deg, transparent 0 15px, rgba(255,255,255,0.03) 15px 16px),
    repeating-linear-gradient(90deg, transparent 0 15px, rgba(255,255,255,0.03) 15px 16px),
    var(--bg);
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
}

.card {
  width: 100%;
  max-width: 440px;
  background: var(--panel);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--border);
  padding: 28px 22px;
  text-align: center;
}

.title {
  margin: 0 0 4px;
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.subtitle {
  margin: 0 0 24px;
  font-size: 0.95rem;
  color: var(--accent2);
  letter-spacing: 1px;
}

.field {
  display: flex;
  flex-direction: column;
  text-align: left;
  margin-bottom: 18px;
  flex: 1;
}

label {
  margin-bottom: 6px;
  font-size: 0.9rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent2);
}

input, select {
  width: 100%;
  font: inherit;
  font-size: 1.1rem;
  padding: 12px;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input:hover, select:hover { border-color: var(--accent2); }

input:focus-visible, select:focus-visible, button:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 210, 63, 0.5);
}

.row {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  margin-bottom: 18px;
}

.row .field { margin-bottom: 0; }

.swap {
  font: inherit;
  font-size: 1.4rem;
  line-height: 1;
  padding: 12px 14px;
  cursor: pointer;
  color: var(--border);
  background: var(--accent);
  border: 3px solid var(--border);
  border-radius: 0;
  box-shadow: 4px 4px 0 var(--border);
  transition: transform 0.08s, box-shadow 0.08s, background 0.15s;
}

.swap:hover { background: var(--accent2); }
.swap:active { transform: translate(4px, 4px); box-shadow: 0 0 0 var(--border); }

.result {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 10px;
  padding: 18px;
  margin-bottom: 18px;
  background: var(--bg);
  border: 3px solid var(--border);
}

.result-value {
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent);
  word-break: break-all;
}

.result-code {
  font-size: 1rem;
  color: var(--accent2);
  letter-spacing: 1px;
}

.note {
  margin: 0;
  font-size: 0.8rem;
  color: rgba(244, 244, 255, 0.6);
}

@media (max-width: 420px) {
  .row { flex-direction: column; align-items: stretch; }
  .swap { align-self: center; }
  .result-value { font-size: 1.6rem; }
}

(function () {
  "use strict";

  // Fixed built-in rates relative to 1 USD.
  var RATES = { USD: 1, EUR: 0.92, JPY: 149.5, CNY: 7.24 };
  var CURRENCIES = ["USD", "EUR", "JPY", "CNY"];

  var amountEl = document.getElementById("amount");
  var fromEl = document.getElementById("from");
  var toEl = document.getElementById("to");
  var swapEl = document.getElementById("swap");
  var resultEl = document.getElementById("result");
  var resultCodeEl = document.getElementById("result-code");

  function populate(select, selected) {
    CURRENCIES.forEach(function (code) {
      var opt = document.createElement("option");
      opt.value = code;
      opt.textContent = code;
      select.appendChild(opt);
    });
    select.value = selected;
  }

  populate(fromEl, "USD");
  populate(toEl, "EUR");

  function convert() {
    var raw = parseFloat(amountEl.value);
    var amount = isFinite(raw) && raw >= 0 ? raw : 0;
    var from = fromEl.value;
    var to = toEl.value;
    var usd = amount / RATES[from];
    var out = usd * RATES[to];
    resultEl.textContent = out.toFixed(2);
    resultCodeEl.textContent = to;
  }

  amountEl.addEventListener("input", convert);
  fromEl.addEventListener("change", convert);
  toEl.addEventListener("change", convert);

  swapEl.addEventListener("click", function () {
    var tmp = fromEl.value;
    fromEl.value = toEl.value;
    toEl.value = tmp;
    convert();
  });

  convert();
})();
